// 5x7 dot font, one original table so the LCDs need no bundled display font
static const uint8_t* glyph(char c) { static const std::map<char, std::array<uint8_t, 5>> t = {
 {'A',{0x7e,0x11,0x11,0x11,0x7e}},{'B',{0x7f,0x49,0x49,0x49,0x36}},{'C',{0x3e,0x41,0x41,0x41,0x22}},{'D',{0x7f,0x41,0x41,0x22,0x1c}},{'E',{0x7f,0x49,0x49,0x49,0x41}},{'F',{0x7f,0x09,0x09,0x09,0x01}},{'G',{0x3e,0x41,0x49,0x49,0x7a}},{'H',{0x7f,0x08,0x08,0x08,0x7f}},{'I',{0x00,0x41,0x7f,0x41,0x00}},{'J',{0x20,0x40,0x41,0x3f,0x01}},{'K',{0x7f,0x08,0x14,0x22,0x41}},{'L',{0x7f,0x40,0x40,0x40,0x40}},{'M',{0x7f,0x02,0x0c,0x02,0x7f}},{'N',{0x7f,0x04,0x08,0x10,0x7f}},{'O',{0x3e,0x41,0x41,0x41,0x3e}},{'P',{0x7f,0x09,0x09,0x09,0x06}},{'Q',{0x3e,0x41,0x51,0x21,0x5e}},{'R',{0x7f,0x09,0x19,0x29,0x46}},{'S',{0x46,0x49,0x49,0x49,0x31}},{'T',{0x01,0x01,0x7f,0x01,0x01}},{'U',{0x3f,0x40,0x40,0x40,0x3f}},{'V',{0x1f,0x20,0x40,0x20,0x1f}},{'W',{0x3f,0x40,0x38,0x40,0x3f}},{'X',{0x63,0x14,0x08,0x14,0x63}},{'Y',{0x07,0x08,0x70,0x08,0x07}},{'Z',{0x61,0x51,0x49,0x45,0x43}},
 {'0',{0x3e,0x51,0x49,0x45,0x3e}},{'1',{0x00,0x42,0x7f,0x40,0x00}},{'2',{0x42,0x61,0x51,0x49,0x46}},{'3',{0x21,0x41,0x45,0x4b,0x31}},{'4',{0x18,0x14,0x12,0x7f,0x10}},{'5',{0x27,0x45,0x45,0x45,0x39}},{'6',{0x3c,0x4a,0x49,0x49,0x30}},{'7',{0x01,0x71,0x09,0x05,0x03}},{'8',{0x36,0x49,0x49,0x49,0x36}},{'9',{0x06,0x49,0x49,0x29,0x1e}},{'-',{0x08,0x08,0x08,0x08,0x08}},{'\'',{0x00,0x05,0x03,0x00,0x00}},{'.',{0x00,0x60,0x60,0x00,0x00}},{'/',{0x20,0x10,0x08,0x04,0x02}},{'+',{0x08,0x08,0x3e,0x08,0x08}} };
 auto i = t.find(c); return i == t.end() ? nullptr : i->second.data(); }
static void dots(Graphics& g, const String& s, Rectangle<float> r, Colour c, float cell) { float w = s.length() * cell * 6 - cell, x = r.getCentreX() - w / 2, y = r.getCentreY() - cell * 3.5f; if (w > r.getWidth()) { cell = r.getWidth() / (s.length() * 6); w = s.length() * cell * 6; x = r.getX(); y = r.getCentreY() - cell * 3.5f; } g.setColour(c); for (auto ch : s) { if (auto* p = glyph((char)ch)) for (int i = 0; i < 5; ++i) for (int j = 0; j < 7; ++j) if (p[i] >> j & 1) g.fillRoundedRectangle(x + i * cell, y + j * cell, cell * .82f, cell * .82f, cell * .22f); x += cell * 6; } }
struct Skin : LookAndFeel_V4 { Image knob = img("knob_png"); void drawRotarySlider(Graphics& g, int, int, int w, int h, float pos, float a0, float a1, Slider& s) override { auto b = Rectangle<float>(0, 0, (float)w, (float)h); float d = (float)s.getProperties().getWithDefault("cap", jmin(w, h) * .74f), cx = b.getCentreX(), cy = b.getCentreY(), r = d / 2; bool plain = s.getProperties().getWithDefault("plate", false);
        if (s.getProperties().getWithDefault("ticks", false)) { g.setColour(cream.withAlpha(.75f)); for (int i = 0; i <= 12; ++i) { float a = a0 + (a1 - a0) * i / 12.f; g.drawLine(cx + std::sin(a) * (r + 5), cy - std::cos(a) * (r + 5), cx + std::sin(a) * (r + (i % 3 ? 11 : 15)), cy - std::cos(a) * (r + (i % 3 ? 11 : 15)), 1.6f); } }
        if (!plain) g.drawImage(knob, Rectangle<float>(cx - r, cy - r, d, d), RectanglePlacement::stretchToFit); float a = a0 + pos * (a1 - a0); g.setColour(cream); Path p; p.addRoundedRectangle(-d * .028f, -r * .96f, d * .056f, r * .62f, d * .02f); g.fillPath(p, AffineTransform::rotation(a).translated(cx, cy)); }
    Label* createSliderTextBox(Slider& s) override { auto* l = LookAndFeel_V4::createSliderTextBox(s); l->setColour(Label::textColourId, cream); l->setColour(Label::backgroundColourId, Colours::transparentBlack); l->setColour(Label::outlineColourId, Colours::transparentBlack); l->setFont(bar(20, false)); return l; } 
    PopupMenu::Options getOptionsForComboBoxPopupMenu(ComboBox& c, Label& l) override { return LookAndFeel_V4::getOptionsForComboBoxPopupMenu(c, l); }
    float menuFont = 42.f; Font getPopupMenuFont() override { return bar(menuFont, false); } int getPopupMenuBorderSize() override { return roundToInt(menuFont * .4f); }
    void drawPopupMenuBackground(Graphics& g, int, int) override { g.fillAll(Colour(0xff17171a)); } };
struct Knob : Slider { Knob(float cap, bool ticks = false, bool plate = false) { setSliderStyle(RotaryVerticalDrag); setTextBoxStyle(NoTextBox, false, 0, 0); setRotaryParameters(MathConstants<float>::pi * 1.25f, MathConstants<float>::pi * 2.75f, true); getProperties().set("cap", cap); getProperties().set("ticks", ticks); getProperties().set("plate", plate); setPopupDisplayEnabled(true, true, nullptr); setVelocityBasedMode(false); setScrollWheelEnabled(true); } };
struct Toggle : ToggleButton { Image t = img("toggle_png"); void paintButton(Graphics& g, bool, bool) override { auto b = getLocalBounds().toFloat(); if (getToggleState()) g.drawImage(t, b); else { Graphics::ScopedSaveState s(g); g.addTransform(AffineTransform::verticalFlip(b.getHeight())); g.setOpacity(.82f); g.drawImage(t, b); } } };
