struct Flat : Button { String tx; bool lit = false; float fs; Flat(String t, float size = 24) : Button(t), tx(t), fs(size) {} void paintButton(Graphics& g, bool o, bool) override { auto b = getLocalBounds().toFloat().reduced(1.5f); bool on = lit || getToggleState(); g.setColour(on ? cream : Colour(0xff121212)); g.fillRoundedRectangle(b, 6); g.setColour(cream.withAlpha(o ? 1 : .6f)); g.drawRoundedRectangle(b, 6, 1.6f); g.setColour(on ? Colour(0xff151515) : cream); g.setFont(bar(fs)); g.drawText(tx, b, Justification::centred); } };
struct Lcd : Component { std::function<String()> text; std::function<void()> click; Colour col = lcdC; float cell = 5; bool frame = false; void paint(Graphics& g) override { auto b = getLocalBounds().toFloat(); if (frame) { g.setColour(Colour(0xff0d0f0f)); g.fillRoundedRectangle(b, 5); g.setColour(cream.withAlpha(.35f)); g.drawRoundedRectangle(b.reduced(.8f), 5, 1.4f); b.reduce(10, 0); } dots(g, text ? text() : String(), b, col, cell); } void mouseDown(const MouseEvent&) override { if (click) click(); } };
struct Device : Component { std::function<String()> name, icon; std::function<void()> click; void mouseDown(const MouseEvent&) override { if (click) click(); }
    void paint(Graphics& g) override { auto r = getLocalBounds().toFloat(); auto n = icon ? icon() : String("phone"); auto a = r.withTrimmedBottom(80).reduced(55, 30); Path p; float x = a.getX(), y = a.getY(), w = a.getWidth(), h = a.getHeight();
        if (n == "phone") { p.addRoundedRectangle(x, y + h * .05f, w, h * .22f, h * .11f); p.addRoundedRectangle(x + w * .2f, y + h * .35f, w * .6f, h * .6f, 10); for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) p.addEllipse(x + w * (.33f + i * .12f), y + h * (.47f + j * .14f), w * .06f, w * .06f); }
        else if (n == "mobile") { p.addRoundedRectangle(x + w * .3f, y, w * .4f, h, 14); p.addRectangle(x + w * .35f, y + h * .1f, w * .3f, h * .72f); }
        else if (n == "laptop") { p.addRoundedRectangle(x + w * .12f, y + h * .1f, w * .76f, h * .6f, 8); p.addRoundedRectangle(x, y + h * .76f, w, h * .1f, 6); }
        else if (n == "radio") { p.addRoundedRectangle(x, y + h * .22f, w, h * .66f, 12); p.addEllipse(x + w * .62f, y + h * .36f, w * .26f, w * .26f); for (int i = 0; i < 6; ++i) p.addRectangle(x + w * .08f, y + h * (.36f + i * .07f), w * .46f, 2.5f); p.startNewSubPath(x + w * .2f, y + h * .22f); p.lineTo(x + w * .7f, y); }
        else if (n == "walkie") { p.addRoundedRectangle(x + w * .3f, y + h * .24f, w * .4f, h * .76f, 10); p.startNewSubPath(x + w * .4f, y + h * .24f); p.lineTo(x + w * .4f, y); for (int i = 0; i < 5; ++i) p.addRectangle(x + w * .36f, y + h * (.38f + i * .06f), w * .28f, 2.5f); }
        else if (n == "horn") { p.startNewSubPath(x + w * .1f, y + h * .4f); p.lineTo(x + w * .35f, y + h * .4f); p.lineTo(x + w * .9f, y + h * .08f); p.lineTo(x + w * .9f, y + h * .92f); p.lineTo(x + w * .35f, y + h * .6f); p.lineTo(x + w * .1f, y + h * .6f); p.closeSubPath(); }
        else if (n == "car") { p.startNewSubPath(x, y + h * .75f); p.lineTo(x, y + h * .5f); p.lineTo(x + w * .2f, y + h * .45f); p.lineTo(x + w * .34f, y + h * .22f); p.lineTo(x + w * .7f, y + h * .22f); p.lineTo(x + w * .86f, y + h * .47f); p.lineTo(x + w, y + h * .55f); p.lineTo(x + w, y + h * .75f); p.closeSubPath(); p.addEllipse(x + w * .15f, y + h * .66f, w * .17f, w * .17f); p.addEllipse(x + w * .68f, y + h * .66f, w * .17f, w * .17f); }
        else if (n == "tape") { p.addRoundedRectangle(x, y + h * .2f, w, h * .6f, 8); p.addEllipse(x + w * .2f, y + h * .36f, w * .18f, w * .18f); p.addEllipse(x + w * .62f, y + h * .36f, w * .18f, w * .18f); }
        else { p.addRoundedRectangle(x + w * .2f, y, w * .6f, h, 8); p.addEllipse(x + w * .34f, y + h * .1f, w * .32f, w * .32f); p.addEllipse(x + w * .28f, y + h * .46f, w * .44f, w * .44f); }
        g.setColour(cream); g.strokePath(p, PathStrokeType(3.5f)); dots(g, name ? name().toUpperCase() : String(), r.withTop(r.getBottom() - 72).reduced(12, 0), lcdC, 4.2f); } };
